const $=s=>document.querySelector(s);
const labels=[['행정실','보건실','도서관','상담실','1-1 교실','1-2 교실','교무실','휴게실'],['2-1 교실','2-2 교실','과학실','컴퓨터실','2-3 교실','미술실','음악실','자율학습실'],['3-1 교실','3-2 교실','물리실','화학실','3-3 교실','세미나실','창작실','스터디룸']];
const accessValues=[[90,92,86,81,88,84,89,78],[85,82,48,79,87,74,68,83],[80,76,58,64,82,78,71,86]];
const rooms=labels.flatMap((names,fi)=>names.map((name,i)=>{const floor=fi+1;return{id:String(floor*100+i+1),name,floor,index:i,x:110+(i%4)*164,y:i<4?112:292,w:158,h:112,area:Math.round(49+i*2.7),width:i===2?78:i===6?85:100+(i%3)*5,access:accessValues[fi][i],temp:Math.round((22.5+((i*3+fi*2)%8)*.7)*10)/10,noise:39+((i*7+fi*3)%25),light:180+((i*59+fi*23)%410),co2:590+((i*123+fi*241)%1050),occupancy:18+((i*17+fi*11)%78)};}));
const clamp=(v,a=0,b=100)=>Math.min(b,Math.max(a,v));
function comfort(r){return Math.round((clamp(100-Math.abs(r.temp-24)*12)+clamp(100-Math.max(0,r.noise-40)*2.3)+clamp(100-Math.max(0,350-r.light)*.24)+clamp(100-Math.max(0,r.co2-800)*.09))/4)}
const score=r=>Math.round((r.access+comfort(r))/2);const average=arr=>Math.round(arr.reduce((a,r)=>a+score(r),0)/arr.length);
let floor=2,selected='203',layer='integrated',zoom=1,routeResult=null;
const current=()=>rooms.find(r=>r.id===selected);const status=v=>v>=80?'양호':v>=65?'주의':'취약';
const colors=['#c0d5b4','#e5d8ad','#dfbfa8'];const tone=v=>v>=80?colors[0]:v>=65?colors[1]:colors[2];
const layerInfo={integrated:['통합 점수','점'],access:['접근성','점'],comfort:['쾌적성','점'],temp:['온도','°C'],noise:['소음','dB'],light:['조도','lx'],co2:['CO₂','ppm'],occupancy:['이용률','%']};
function value(r){return layer==='integrated'?score(r):layer==='comfort'?comfort(r):r[layer]}
function quality(r){return ['integrated','access','comfort'].includes(layer)?value(r):layer==='temp'?clamp(100-Math.abs(r.temp-24)*15):layer==='noise'?clamp(100-Math.max(0,r.noise-40)*3):layer==='light'?clamp(100-Math.max(0,350-r.light)*.3):layer==='co2'?clamp(100-Math.max(0,r.co2-800)*.12):clamp(100-Math.max(0,r.occupancy-45)*1.5)}
function render(){renderMetrics();$('#floors').innerHTML=[1,2,3].map(f=>`<button class="${f===floor?'active':''}" data-floor="${f}">${f}F</button>`).join('');$('#floorLabel').textContent=floor+'F';$('#mapCount').textContent=`8개 공간 · ${floor}층`;renderMap();renderDetails();renderPriorities();$('#floorChart').innerHTML=[3,2,1].map(f=>`<div class="floor-chart-row ${f===floor?'current':''}"><span>${f}F</span><div class="bar-track"><i style="width:${average(rooms.filter(r=>r.floor===f))}%"></i></div><b>${average(rooms.filter(r=>r.floor===f))}</b></div>`).join('');}
function renderMetrics(){$('#metrics').innerHTML=[['분석 공간',24,'개','3개 층의 실내 공간','▦'],['평균 접근성',Math.round(rooms.reduce((a,r)=>a+r.access,0)/24),'점','전체 공간 기준 · 100점 만점','⌁'],['평균 쾌적성',Math.round(rooms.reduce((a,r)=>a+comfort(r),0)/24),'점','온도 · 소음 · 조도 · 공기질','◉'],['개선 검토 공간',rooms.filter(r=>score(r)<65).length,'개','통합 점수 65점 미만','⚑']].map(([name,n,u,note,icon],i)=>`<div class="metric ${i===3?'warning':''}"><div class="metric-label">${name}</div><span class="metric-icon">${icon}</span><div class="metric-number">${n}<small>${u}</small></div><div class="metric-note">${note}</div></div>`).join('')}
function renderMap(){let rs=rooms.filter(r=>r.floor===floor);$('#floorMap').innerHTML=`<defs><pattern id="stairs" width="14" height="8" patternUnits="userSpaceOnUse"><path d="M0 0H14" stroke="#aebda6" stroke-width="2"/></pattern></defs><rect x="48" y="98" width="792" height="321" rx="3" fill="#e4eade" stroke="#afbea7" stroke-width="2"/><rect x="96" y="231" width="696" height="53" fill="#f2f5ee"/><text x="450" y="262" text-anchor="middle" fill="#a7b39d" font-size="10" letter-spacing="7">C O R R I D O R</text><rect x="57" y="112" width="40" height="112" fill="url(#stairs)"/><rect x="57" y="292" width="40" height="112" fill="url(#stairs)"/><text x="77" y="252" text-anchor="middle" fill="#84957c" font-size="10">↕ 계단</text><rect x="781" y="112" width="48" height="112" fill="url(#stairs)"/><rect x="781" y="292" width="48" height="112" fill="#ceddcb"/><text x="805" y="340" text-anchor="middle" fill="#638365" font-size="20">↕</text><text x="805" y="366" text-anchor="middle" fill="#638365" font-size="8">ELEV.</text>${rs.map(r=>`<g class="room ${r.id===selected?'selected':''}" data-room="${r.id}" tabindex="0" role="button" aria-label="${r.id}호 ${r.name}, ${layerInfo[layer][0]} ${value(r)}"><rect x="${r.x}" y="${r.y}" width="${r.w}" height="${r.h}" fill="${tone(quality(r))}" rx="2"/><text x="${r.x+13}" y="${r.y+21}" font-size="9" fill="#6c7e61">${r.id}</text><text x="${r.x+79}" y="${r.y+51}" text-anchor="middle" font-size="13" font-weight="500" fill="#435c40">${r.name}</text><text x="${r.x+79}" y="${r.y+73}" text-anchor="middle" font-size="10" fill="#728465">${value(r)}${layerInfo[layer][1]}</text><circle class="sensor" cx="${r.x+139}" cy="${r.y+16}" r="3"/><path d="M${r.x+64} ${iDoor(r)}h28" stroke="#fafcf7" stroke-width="7"/><path d="M${r.x+64} ${iDoor(r)}v${r.index<4?-20:20}h20" fill="none" stroke="#9dac90" stroke-width="1"/></g>`).join('')}${routeResult?routeSvg():''}<text x="445" y="459" text-anchor="middle" fill="#a5b19c" font-size="9" letter-spacing="3">MIRAE HIGH SCHOOL · ${floor}F</text>`;$('#legend').innerHTML=['양호 80+','주의 65–79','취약 <65'].map((s,i)=>`<span><i class="legend-dot" style="background:${colors[i]}"></i>${s}</span>`).join('');if(!['integrated','access','comfort'].includes(layer))$('#legend').innerHTML='<span>환경 상태: </span>'+['양호','주의','취약'].map((s,i)=>`<span><i class="legend-dot" style="background:${colors[i]}"></i>${s}</span>`).join('')}
function iDoor(r){return r.index<4?r.y+r.h:r.y}
function renderDetails(){const r=current(),c=comfort(r),s=score(r);$('#details').innerHTML=`<div class="detail-top"><span>SPACE INSIGHT</span><span class="badge">${status(s)} · ${r.floor}F</span></div><h3>${r.id}호 ${r.name}</h3><div class="room-meta">본관 ${r.floor}층 &nbsp; / &nbsp; ${r.area} m² &nbsp; / &nbsp; 센서 1개</div><div class="score-row"><div class="score-ring" style="--score:${s}"><strong>${s}</strong></div><p>공간 통합 점수<br><b>${s>=80?'쾌적한 공간입니다':s>=65?'개선 여지가 있습니다':'우선 검토가 필요합니다'}</b></p></div><div class="score-bars">${[['접근성',r.access],['쾌적성',c]].map(([a,b])=>`<div><div class="score-bar-head"><span>${a}</span><span>${b} <small>/ 100</small></span></div><div class="bar-track"><i style="width:${b}%"></i></div></div>`).join('')}</div><div class="env-grid">${[['온도',r.temp,'°C'],['소음',r.noise,'dB'],['조도',r.light,'lx'],['공기질 · CO₂',r.co2,'ppm']].map(([a,b,c])=>`<div><small>${a}</small><b>${b}</b><em>${c}</em></div>`).join('')}</div><div class="insight"><b>✧ 공간 인사이트</b>${reason(r)}<br>출입구 폭 ${r.width}cm · 가상 이용률 ${r.occupancy}%</div><button class="detail-action" id="simulate">개선 시뮬레이션 시작 &nbsp; ↗</button>`;$('#simulate').onclick=openSimulation;}
function reason(r){let a=[];if(r.width<90)a.push('출입구가 좁아 이동에 제약이 있습니다.');if(r.temp>26)a.push('실내 온도가 높습니다.');if(r.noise>55)a.push('소음 관리가 필요합니다.');if(r.light<300)a.push('조명 개선을 검토하세요.');if(r.co2>1100)a.push('환기 개선을 검토하세요.');return a.slice(0,2).join(' ')||'접근성과 환경을 정기적으로 모니터링하세요.'}
function renderPriorities(){$('#priorities').innerHTML=[...rooms].sort((a,b)=>score(a)-score(b)).slice(0,3).map((r,i)=>`<div class="priority-item" role="button" tabindex="0" data-select="${r.id}"><span class="rank">0${i+1}</span><div><b>${r.id}호 ${r.name}</b><small>${reason(r)}</small></div><strong>${score(r)}<small>통합 점수</small></strong><span>↗</span></div>`).join('')}
function selectRoom(id){selected=id;floor=current().floor;render()}
$('#floors').onclick=e=>{if(e.target.dataset.floor){floor=+e.target.dataset.floor;selected=rooms.find(r=>r.floor===floor).id;render()}};
$('#floorMap').onclick=e=>{let room=e.target.closest('[data-room]');if(room)selectRoom(room.dataset.room)};
$('#priorities').onclick=e=>{let room=e.target.closest('[data-select]');if(room)selectRoom(room.dataset.select)};
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-room],[data-select]'))selectRoom(e.target.dataset.room||e.target.dataset.select)});
$('#layer').onchange=e=>{layer=e.target.value;renderMap()};
function setZoom(n){zoom=clamp(n,.7,1.7);$('#mapViewport').style.transform=`scale(${zoom})`};$('#zoomIn').onclick=()=>setZoom(zoom+.15);$('#zoomOut').onclick=()=>setZoom(zoom-.15);$('#zoomReset').onclick=()=>setZoom(1);
$('#view3d').onclick=()=>{$('.map-area').classList.add('isometric');$('#view3d').classList.add('active');$('#view2d').classList.remove('active');toast('평면도의 입체 보기입니다. 실제 3D 건물 모델은 아닙니다.')};$('#view2d').onclick=()=>{$('.map-area').classList.remove('isometric');$('#view2d').classList.add('active');$('#view3d').classList.remove('active')};
const modal=$('#modal');function show(html){$('#modalContent').innerHTML=html;if(!modal.open)modal.showModal()}$('#closeModal').onclick=()=>modal.close();modal.onclick=e=>{if(e.target===modal)modal.close()};let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function openMethod(){show(`<div class="eyebrow">METHODOLOGY · SAMPLE DATA</div><h2>분석 기준과 데이터</h2><p>미래고등학교는 가상의 3층 건물입니다. 24개 공간의 좌표는 건물 내부 미터 단위이며 실제 지리적 위치에 해당하지 않습니다. 환경값과 접근성 기초 점수는 기능 시연용으로 생성했습니다.</p><p><b>통합 점수</b> = 접근성 × 0.5 + 쾌적성 × 0.5<br><b>쾌적성</b> = 온도·소음·조도·CO₂ 하위 점수의 산술평균<br>온도: 100 − |T−24| × 12<br>소음: 100 − max(0, dB−40) × 2.3<br>조도: 100 − max(0, 350−lx) × 0.24<br>CO₂: 100 − max(0, ppm−800) × 0.09<br>각 하위 점수는 0~100으로 제한합니다.</p><p>80점 이상 양호, 65~79점 주의, 65점 미만 취약으로 분류합니다. 접근성 점수는 예시 기초값이며 법규 평가 점수가 아닙니다. 경로는 복도 연결 그래프에서 Dijkstra 알고리즘으로 계산합니다. 개선 효과는 가정한 가산점이며 실측·AI 예측 결과가 아닙니다.</p>`)}$('#method').onclick=openMethod;$('#info').onclick=openMethod;$('#building').onclick=()=>toast('현재 프로젝트: 미래고등학교 본관 · 3개 층 · 가상 데이터');
function openSimulation(){const r=current();show(`<div class="eyebrow">WHAT-IF SIMULATION</div><h2>${r.id}호 ${r.name} 개선 시뮬레이션</h2><p>개선안을 선택하고 예상 점수와 비용을 비교하세요. 아래 효과와 비용은 시연용 가정값입니다.</p><div id="simOptions">${[['door','출입구 확장 및 단차 개선','접근성 +20점 · 예상 300만원'],['led','LED 조명 및 흡음 개선','쾌적성 +10점 · 예상 150만원'],['vent','환기·냉방 설비 개선','쾌적성 +17점 · 예상 500만원']].map(([id,n,d])=>`<label class="simulation-option"><input type="checkbox" value="${id}"><span>${n}<small>${d}</small></span></label>`).join('')}</div><div id="simResult"></div><button class="primary" id="simExport">시나리오 저장 (JSON)</button>`);function update(){const checked=[...$('#simOptions').querySelectorAll(':checked')].map(e=>e.value);const a=clamp(r.access+(checked.includes('door')?20:0)),c=clamp(comfort(r)+(checked.includes('led')?10:0)+(checked.includes('vent')?17:0)),s=Math.round((a+c)/2),cost=checked.reduce((n,v)=>n+({door:300,led:150,vent:500}[v]),0);$('#simResult').innerHTML=`<div class="sim-result"><div><small>현재 통합 점수</small><strong>${score(r)}</strong></div><span>→</span><div><small>개선 후 가정 점수</small><strong>${s}</strong></div><div><small>예상 개선</small><strong style="color:#18735b">+${s-score(r)}</strong></div></div><p>접근성 ${a}점 · 쾌적성 ${c}점 · 예상 비용 ${cost.toLocaleString()}만원</p>`;$('#simExport').onclick=()=>download(`scenario-${r.id}.json`,JSON.stringify({dataType:'synthetic-scenario',room:r.id,actions:checked,before:score(r),after:s,access:a,comfort:c,estimatedCostKRW:cost*10000,note:'효과·비용은 기능 시연용 가정값'},null,2),'application/json')};$('#simOptions').onchange=update;update()}
function buildGraph(mode){const graph={};const add=(id,x,y,f)=>graph[id]={x,y,f,edges:[]};const link=(a,b,cost)=>{graph[a].edges.push([b,cost]);graph[b].edges.push([a,cost])};for(let f=1;f<=3;f++){const xs=[77,189,353,517,681,805];xs.forEach((x,i)=>add(`c${f}-${i}`,x,257,f));for(let i=0;i<5;i++)link(`c${f}-${i}`,`c${f}-${i+1}`,(xs[i+1]-xs[i])*.07);rooms.filter(r=>r.floor===f).forEach(r=>{add(r.id,r.x+79,r.y+56,f);if(mode!=='wheelchair'||r.width>=90)link(r.id,`c${f}-${r.index%4+1}`,6+(mode==='quiet'?Math.max(0,r.noise-45)*.6:0))});if(f>1){if(mode!=='wheelchair')link(`c${f}-0`,`c${f-1}-0`,8);link(`c${f}-5`,`c${f-1}-5`,mode==='shortest'?22:10)}}return graph}
function findRoute(start,end,mode){const g=buildGraph(mode),dist={},prev={},queue=new Set(Object.keys(g));for(const k of queue)dist[k]=Infinity;dist[start]=0;while(queue.size){const u=[...queue].reduce((a,b)=>dist[a]<dist[b]?a:b);if(!isFinite(dist[u]))break;queue.delete(u);if(u===end)break;for(const [v,c]of g[u].edges)if(dist[u]+c<dist[v]){dist[v]=dist[u]+c;prev[v]=u}}if(!isFinite(dist[end]))return null;let path=[],p=end;while(p){path.unshift(p);p=prev[p]}let meters=0;for(let i=1;i<path.length;i++){const a=g[path[i-1]],b=g[path[i]];meters+=a.f===b.f?Math.hypot(a.x-b.x,a.y-b.y)*.07:4}return{path,g,meters:Math.round(meters),cost:dist[end],mode,start,end}}
function openRoute(){show(`<div class="eyebrow">PERSONALIZED WAYFINDING</div><h2>나에게 맞는 실내 경로</h2><p>계단·엘리베이터와 복도 연결망을 따라 경로를 계산합니다. 동일 층과 층간 이동 모두 지원합니다.</p><div class="form-row"><label>출발 공간<select id="routeStart">${roomOptions('101')}</select></label><label>도착 공간<select id="routeEnd">${roomOptions(selected)}</select></label></div><div class="form-row"><label>이동 조건<select id="routeMode"><option value="shortest">일반 · 최단 경로</option><option value="wheelchair">휠체어 · 계단 회피 / 출입구 90cm 이상</option><option value="quiet">저소음 우선 · 소음 가중 비용</option></select></label></div><button class="primary" id="calculateRoute">경로 계산하기</button><div id="routeResult"></div>`);$('#calculateRoute').onclick=()=>{let start=$('#routeStart').value,end=$('#routeEnd').value,mode=$('#routeMode').value;if(start===end){$('#routeResult').innerHTML='<p>출발지와 목적지를 다르게 선택하세요.</p>';return}const result=findRoute(start,end,mode);routeResult=result;renderMap();if(!result){$('#routeResult').innerHTML='<div class="route-result">선택한 조건으로 이동 가능한 경로가 없습니다. 출입구 폭 또는 이동 조건을 확인하세요.</div>';return}const normal=findRoute(start,end,'shortest');$('#routeResult').innerHTML=`<div class="route-result"><b>선택 경로 약 ${result.meters}m</b> · 일반 최단 경로 약 ${normal.meters}m<br>${result.path.filter(k=>!k.startsWith('c')).map(id=>`${id}호`).join(' → ')}<br>${result.path.some((k,i,a)=>i>0&&result.g[k].f!==result.g[a[i-1]].f)?(result.path.some(k=>k.endsWith('-0'))?'계단 이용':'엘리베이터 이용'):'같은 층 이동'} · 예상 ${Math.max(1,Math.ceil(result.meters/45))}분 (시연용)<br><small>녹색 점선으로 각 층의 경로를 확인할 수 있습니다.</small><br><button class="detail-action" id="showRoute">지도에서 출발 층 보기 ↗</button></div>`;$('#showRoute').onclick=()=>{selected=start;floor=rooms.find(r=>r.id===start).floor;render();modal.close();toast('층 버튼을 전환하면 해당 층의 경로가 표시됩니다.')}}}
function roomOptions(id){return rooms.map(r=>`<option value="${r.id}" ${r.id===id?'selected':''}>${r.id}호 ${r.name} (${r.floor}F)</option>`).join('')}
function routeSvg(){let segments=[],points=[];for(const id of routeResult.path){const p=routeResult.g[id];if(p.f===floor){points.push(`${p.x},${p.y}`)}else if(points.length){segments.push(points);points=[]}}if(points.length)segments.push(points);return segments.map(s=>`<polyline class="path-line" points="${s.join(' ')}"/>`).join('')}
function openAll(){show(`<div class="eyebrow">SPACE DIRECTORY</div><h2>전체 공간 · 개선 우선순위</h2><p>통합 점수가 낮은 순서입니다. 공간을 선택하면 지도에서 확인할 수 있습니다.</p><div style="max-height:420px;overflow:auto"><table class="table"><thead><tr><th>공간</th><th>접근성</th><th>쾌적성</th><th>통합</th></tr></thead><tbody>${[...rooms].sort((a,b)=>score(a)-score(b)).map(r=>`<tr><td><button style="background:none;border:0;text-align:left;color:#18735b" data-directory="${r.id}">${r.id}호 ${r.name} ↗</button></td><td>${r.access}</td><td>${comfort(r)}</td><td>${score(r)}</td></tr>`).join('')}</tbody></table></div>`);$('#modalContent').onclick=e=>{if(e.target.dataset.directory){selectRoom(e.target.dataset.directory);modal.close()}}}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('파일을 저장했습니다.')}
function exportCSV(){let rows=[['데이터 구분','공간ID','층','공간명','면적_m2','출입구_cm','접근성','쾌적성','통합점수','온도_C','소음_dB','조도_lx','CO2_ppm','이용률_pct'],...rooms.map(r=>['가상 데이터',r.id,r.floor,r.name,r.area,r.width,r.access,comfort(r),score(r),r.temp,r.noise,r.light,r.co2,r.occupancy])];download('indoor-space-analysis-sample.csv','\uFEFF'+rows.map(a=>a.join(',')).join('\r\n'),'text/csv;charset=utf-8')}
function openReport(){show(`<div class="eyebrow">RESEARCH EXPORT</div><h2>분석 보고서 내보내기</h2><p>24개 공간의 기초 환경값, 접근성·쾌적성·통합 점수를 CSV로 저장합니다. 공간 데이터에는 로컬 좌표계의 사각형 폴리곤과 분석 기준이 포함됩니다.</p><p>현재 건물 평균 통합 점수 <b>${average(rooms)}점</b> · 개선 검토 공간 <b>${rooms.filter(r=>score(r)<65).length}개</b><br>가상 데이터 / 센서 실측 아님 / 개선 효과 검증 전</p><button class="primary" id="csvExport">분석 결과 CSV 저장</button> <button class="detail-action" id="spatialExport">공간 데이터 JSON 저장</button>`);$('#csvExport').onclick=exportCSV;$('#spatialExport').onclick=()=>download('indoor-spaces-local.json',JSON.stringify({dataType:'synthetic',coordinateSystem:'local building coordinates in meters; not WGS84',method:'integrated=0.5*access+0.5*comfort; illustrative thresholds',rooms:rooms.map(r=>({...r,comfort:comfort(r),integrated:score(r),polygon:[[r.x*.07,r.y*.07],[(r.x+r.w)*.07,r.y*.07],[(r.x+r.w)*.07,(r.y+r.h)*.07],[r.x*.07,(r.y+r.h)*.07],[r.x*.07,r.y*.07]]}))},null,2),'application/json')}
$('#allSpaces').onclick=openAll;$('#export').onclick=openReport;
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x===b));$('#breadcrumb').textContent=b.querySelector('span').textContent;const tab=b.dataset.tab;if(tab==='route')openRoute();else if(tab==='simulation')openSimulation();else if(tab==='report')openReport();else if(tab==='environment'){layer='temp';$('#layer').value=layer;renderMap();$('#pageTitle').innerHTML='공간의 환경을 자세히 들여다보다<span>.</span>';$('#pageSubtitle').textContent='온도·소음·조도·공기질 레이어로 환경 취약 구역을 탐색하세요.'}else{layer='integrated';$('#layer').value=layer;renderMap();$('#pageTitle').innerHTML='공간을 읽다, 가능성을 발견하다<span>.</span>';$('#pageSubtitle').textContent='접근성과 환경을 함께 살펴보고, 더 나은 공간을 설계하세요.'}});
render();
